function registry(glyphs: TextGlyph[]): Record<string, TextGlyph> {
  const map: Record<string, TextGlyph> = {};
  for (const g of glyphs) map[g.c] = g;
  return map;
}

/** Vendored single-line font registry. See file header for provenance/licenses. */
export const TEXT_FONTS: Record<string, TextFont> = {
  'sans': { id: 'sans', label: 'Sans Single-Line', capHeight: 21, baseline: 22, spaceAdvance: 16, glyphs: registry(font_sans) },
  'sans-bold': { id: 'sans-bold', label: 'Sans Single-Line Bold', capHeight: 21, baseline: 22, spaceAdvance: 16, glyphs: registry(font_sans_bold) },
  'serif': { id: 'serif', label: 'Serif Single-Line', capHeight: 21, baseline: 22, spaceAdvance: 16, glyphs: registry(font_serif) },
  'script': { id: 'script', label: 'Script Single-Line', capHeight: 21, baseline: 22, spaceAdvance: 16, glyphs: registry(font_script) },
  'gothic-english': { id: 'gothic-english', label: 'Gothic English', capHeight: 21, baseline: 22, spaceAdvance: 16, glyphs: registry(font_gothic_english) },
};

/** All vendored font ids, in stable presentation order. */
export const TEXT_FONT_IDS: string[] = ["sans","sans-bold","serif","script","gothic-english"];

/** Look up a font by id; throws on unknown ids (caller bug, not user input). */
export function getTextFont(id: string): TextFont {
  const f = TEXT_FONTS[id];
  if (!f) throw new Error(`unknown text font id: ${id}`);
  return f;
}

/** Display label for a font id; falls back to the id itself. */
export function textFontLabel(id: string): string {
  return TEXT_FONTS[id]?.label ?? id;
}
